"""Complete elliptic integrals K(m), E(m) as piecewise polynomials over the
octaves of p = 1 - m, for p in [2^-10, 2^11) (m in (-2047, 0.99903]).

    uv run --with mpmath==1.4.1 python testdata/gen/fit_ellip_oct.py > zz_ellipOct_coeffs.go

Each octave [2^e, 2^(e+1)) of p is cut into 8 pieces of equal width; on
each, the function of m is interpolated at Chebyshev nodes (fit.cheb_interp,
200 bits) with a fixed degree DEG and converted to monomials in s = m - c,
c = 1 - (piece centre in p), an exact float64. The singularity of K at m = 1
(p = 0) is at least 8 piece half-widths away from any piece, so the degree
needed for 2^-62 does not grow towards p = 0 or p = 2^11: the maximum
interpolation error over all pieces, checked on 201 points each against
mpmath, is printed in the header. The constant term is also emitted as a
double-double (c0lo), and since |s q(s)| is below 2% of c0 on every piece
the evaluation c0 + (s q(s) + c0lo) rounds once, within 0.5 ulp plus the
interpolation error.
"""

import mpmath
from mpmath import mp, mpf

from fit import cheb_interp

mp.prec = 200
DEG = 11
EMIN, EMAX, NSUB = -10, 10, 8


def pieces(f):
    out = []
    worst = mpf(0)
    for e in range(EMIN, EMAX + 1):
        p0 = mpf(2) ** e
        for j in range(NSUB):
            plo = p0 * (1 + mpf(j) / NSUB)
            phi = p0 * (1 + mpf(j + 1) / NSUB)
            pc = (plo + phi) / 2
            c = 1 - pc
            assert c == mpf(float(c))
            # interpolate on m in [1 - phi, 1 - plo]; slightly widened so that
            # a rounding of p = 1 - m to the neighbouring piece is covered.
            a, b = 1 - phi, 1 - plo
            pad = (b - a) * mpf(2) ** -20
            cc, co = cheb_interp(f, a - pad, b + pad, DEG)
            assert cc == c
            for k in range(201):
                t = a + (b - a) * k / 200
                pv = mp.fsum(co[i] * (t - c) ** i for i in range(len(co)))
                fv = f(t)
                worst = max(worst, abs((pv - fv) / fv))
            out.append((e, j, c, co))
    return out, worst


def emit(name, f, doc):
    ps, worst = pieces(f)
    print("// %s: %s" % (name, doc))
    print("// Max interpolation error over all pieces: %s relative." % mpmath.nstr(worst, 3))
    print("var %s = [...]octPiece{" % name)
    for e, j, c, co in ps:
        c0lo = float(co[0] - mpf(float(co[0])))
        print("\t// p in 2^%d * [%d/8, %d/8]" % (e, 8 + j, 9 + j))
        print("\t{c: %r, c0lo: %r, coef: [...]float64{" % (float(c), c0lo))
        print("\t\t" + ", ".join(repr(float(v)) for v in reversed(co)) + ",")
        print("\t}},")
    print("}")
    print()


if __name__ == "__main__":
    print("// Code generated by testdata/gen/fit_ellip_oct.py; DO NOT EDIT.")
    print("//")
    print("// Degree-%d interpolants of K(m) and E(m) on %d pieces per octave of" % (DEG, NSUB))
    print("// p = 1 - m, p in [2^%d, 2^%d); mpmath %s at 200 bits." % (EMIN, EMAX + 1, mpmath.__version__))
    print()
    print("package special")
    print()
    emit("ellipKOct", mp.ellipk, "K(m) = sum coef[i] s^(11-i), s = m - c.")
    emit("ellipEOct", mp.ellipe, "E(m) = sum coef[i] s^(11-i), s = m - c.")
